// nda-logos.mjs — both brand marks, bundled with the function.
//
// The executed PDF carries the Brix Beverage round mark and the Alameda Soda
// seal, because the agreement is signed by the company that trades as both.
//
// They are base64 here rather than read off disk on purpose: a Netlify function
// only ships files the bundler can see it import, and a document that renders
// without its letterhead because an asset path moved is worse than a slightly
// larger module. Downscaled to 260 px — a page at 72dpi never needs more, and
// the whole point is that the PDF stays small enough to email.

/** 260 x 260 PNG. */
export const BRIX_LOGO_PNG = '';

/** 260 x 259 PNG. */
export const ALAMEDA_LOGO_PNG = '';

/** Decode to bytes for pdf-lib. Returns null rather than throwing — a missing
 *  logo must never cost us the agreement. */
export function logoBytes(b64) {
  try { return Buffer.from(b64, 'base64'); } catch { return null; }
}
